<"'!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Refill shop · Weekly order sheet</title>
<style>
:root{color-scheme:light;--ink:#203c32;--green:#214d40;--paper:#f8f7f0;--rule:#cfcfc0;--gold:#f0cc7d}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.5 '"'DM Sans',Arial,sans-serif}main,header{max-width:1060px;margin:auto;padding:0 28px}header{display:flex;align-items:center;justify-content:space-between;padding-top:22px;padding-bottom:14px;border-bottom:1px solid var(--rule)}header strong{letter-spacing:.12em;text-transform:uppercase;font-size:13px}button,select{font:inherit;color:inherit;background:transparent;border:1px solid #8f9e91;border-radius:5px;padding:7px 12px;cursor:pointer}button:hover,select:hover{background:#e8eddf}h1,h2,h3,p{margin:0}h1,h2{font-family:'Baskervville',Georgia,serif;font-weight:normal;letter-spacing:-.035em}h1{font-size:clamp(38px,6vw,62px);line-height:1.1;margin:30px 0 7px}h2{font-size:32px;line-height:1.15}h3{font-size:16px}section{margin:30px 0}p{max-width:77ch}.hero{background:var(--green);color:white;border-radius:10px;padding:24px 28px}.hero h2{color:#ffebbb}.cards{display:grid;grid-template-columns:repeat(3,1fr);margin:18px 0;border-block:1px solid #ffffff50;padding:14px 0;gap:14px}.cards b{font:42px Georgia,serif;margin-right:5px}.cards small{display:block;color:#dbe9dd}.capacity{display:flex;gap:15px;align-items:center;flex-wrap:wrap}.meter{height:8px;width:160px;background:#567667;border-radius:6px;overflow:hidden}.meter i{display:block;width:93.3333%;height:100%;background:var(--gold)}.note,small{font-size:14px}.note{margin-top:8px}.picker{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:15px 0}.picker label{font-weight:bold}.scenarios{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin:14px 0}.panel{background:#fffef8;border:1px solid var(--rule);border-top:4px solid #839980;border-radius:5px;padding:16px}.panel:last-child{border-top-color:#cd9b4a}table{width:100%;border-collapse:collapse;font-size:14px;font-variant-numeric:tabular-nums}td,th{border-bottom:1px solid var(--rule);padding:8px 6px;text-align:right}th:first-child,td:first-child{text-align:left}thead th{font-size:12px}tfoot th,tfoot td{font-weight:bold;background:#f1f2e8}.panel table{margin-top:12px}.scroll{overflow-x:auto}.actions button{border:0;text-decoration:underline;text-underline-offset:3px;padding:2px}.active{background:#e6eedf}.wide{min-width:570px}summary{font-weight:bold;cursor:pointer}details{padding:15px 0;border-top:1px solid var(--rule)}details table{margin:10px 0}footer{height:30px}button:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #bd852c;outline-offset:2px}@media(max-width:720px){main,header{padding-inline:15px}.scenarios{grid-template-columns:1fr}.hero{padding:18px}.cards{gap:6px}.cards b{font-size:32px}}@media print{body{font-size:12px}header button,.picker,.actions,details{display:none}.hero,.panel,tfoot,.active{print-color-adjust:exact}.hero{padding:14px}.cards{margin:8px 0;padding:6px 0}h1{font-size:32px;margin-top:12px}h2{font-size:24px}section{margin:14px 0}.scenarios{grid-template-columns:1fr 1fr}.panel{break-inside:avoid}.scroll{overflow:visible}}
</style></head><body><header><strong>Refill shop / Purchasing</strong><button onclick=\"window.print()\">Print sheet</button></header><main>
<h1>Weekly order sheet</h1><p>Choose whole sacks for the next delivery using six weeks of fully stocked sales.</p>
<section class=\"hero\"><h2>Recommended order</h2><div class=\"cards\"><div><h3>Oats</h3><b>2</b> sacks<small>20 kg delivery</small></div><div><h3>Rice</h3><b>2</b> sacks<small>30 kg delivery</small></div><div><h3>Lentils</h3><b>3</b> sacks<small>15 kg delivery</small></div></div>
<div class=\"capacity\"><strong>84 of 90 kg on shelf</strong><span class=\"meter\" aria-hidden=\"true\"><i></i></span><span>6 kg free</span></div><p class=\"note\">This order ties for the lowest historical shortage at 4 kg across six weeks. The fourth sack of lentils would add 5 kg of leftovers every week.</p></section>
<section><h2>Compare orders</h2><p>Replay the same starting inventory and delivery against each week independently.</p>
<div class=\"scroll\"><table class=\"wide\"><thead><tr><th>Order</th><th>Sacks¹</th><th>On shelf</th><th>Avg. short</th><th>Avg. left</th><th class=\"actions\">Inspect</th></tr></thead><tbody id=\"compare\"></tbody></table></div><p class=\"note\">¹ Sack counts follow oats / rice / lentils. Averages are kg per week over all six weeks.</p>
<div class=\"picker\"><label for=\"orders\">Explore all 147 feasible orders</label><select id=\"orders\"></select></div></section>
<section aria-live=\"polite\"><h2 id=\"selection\"></h2><p id=\"stock\"></p><div class=\"scenarios\" id=\"scenarios\"></div><p class=\"note\">Typical demand uses each good’s six-week median. High demand uses week 6, the busiest observed week at 83 kg. Rice peaked separately in week 5 at 41 kg.</p></section>
<details><summary>Inspect all six historical weeks for the selected order</summary><div class=\"scroll\"><table class=\"wide\"><thead><tr><th>Week</th><th>Oats demand</th><th>Rice demand</th><th>Lentils demand</th><th>Short (kg)</th><th>Left (kg)</th></tr></thead><tbody id=\"weeks\"></tbody></table></div></details>
<details><summary>Stock, sack sizes and calculation method</summary><table><thead><tr><th>Good</th><th>Current stock</th><th>Supplier sack</th></tr></thead><tbody><tr><td>Oats</td><td>6 kg</td><td>10 kg</td></tr><tr><td>Rice</td><td>9 kg</td><td>15 kg</td></tr><tr><td>Lentils</td><td>4 kg</td><td>5 kg</td></tr></tbody></table><p>The 19 kg already on hand leaves 71 kg for delivery. Every nonnegative whole-sack combination within that limit is available above. For each good, demand above stock is shortage and stock above demand is leftover. Totals sum across goods. The recommendation minimizes six-week shortage, breaking ties with the lowest leftover. Each observed week has equal weight.</p></details><footer></footer></main>
<script>
const weeks=[[19,32,11],[24,29,15],[22,38,13],[26,34,17],[21,41,12],[28,36,19]];
const names=['Oats','Rice','Lentils'], base=[6,9,4], size=[10,15,5];
const sum=xs=>xs.reduce((a,b)=>a+b,0);
function result(stock,demand){
 const short=demand.map((d,i)=>Math.max(0,d-stock[i]));
 const left=demand.map((d,i)=>Math.max(0,stock[i]-d));
 return {short,left};
}
const plans=[];
for(let oats=0;oats*10<=71;oats++){
 for(let rice=0;oats*10+rice*15<=71;rice++){
  for(let lentils=0;oats*10+rice*15+lentils*5<=71;lentils++){
   const sacks=[oats,rice,lentils],stock=sacks.map((n,i)=>base[i]+size[i]*n);
   const outcomes=weeks.map(d=>result(stock,d));
   plans.push({key:sacks.join('/'),stock,outcomes,short:sum(outcomes.map(r=>sum(r.short))),left:sum(outcomes.map(r=>sum(r.left)))});
  }
 }
}
const ranked=[...plans].sort((a,b)=>a.short-b.short||a.left-b.left);
const choices=[[ranked[0],'Recommended'],[plans.find(p=>p.key==='2/2/2'),'One fewer lentil sack'],[ranked[1],'One extra lentil sack']];
const typical=names.map((_,i)=>{const vals=weeks.map(w=>w[i]).sort((a,b)=>a-b);return (vals[2]+vals[3])/2});
const el=id=>document.getElementById(id);
const cells=items=>items.map(v=>'<td>'+v+'</td>').join('');
const picker=el('orders');
plans.forEach(p=>picker.add(new Option(p.key.split('/').join(' / ')+' sacks · '+sum(p.stock)+' kg on shelf',p.key)));
function scenario(title,demand,stock){
 const {short,left}=result(stock,demand);
 return '<article class=\"panel\"><h3>'+title+'</h3><table><thead><tr><th>kg</th><th>Demand</th><th>Short</th><th>Left</th></tr></thead><tbody>'+names.map((n,i)=>'<tr>'+cells([n,demand[i],short[i],left[i]])+'</tr>').join('')+'</tbody><tfoot><tr>'+cells(['Total',sum(demand),sum(short),sum(left)])+'</tr></tfoot></table></article>';
}
function selectPlan(key){
 const p=plans.find(x=>x.key===key);
 picker.value=key;
 el('compare').innerHTML=choices.map(([x,label])=>'<tr class=\"'+(x.key===key?'active':'')+'\">'+cells([label,x.key,sum(x.stock)+' kg',(x.short/6).toFixed(2),(x.left/6).toFixed(2)])+'<td class=\"actions\"><button aria-label=\"Inspect '+label+'\" data-key=\"'+x.key+'\">View</button></td></tr>').join('');
 el('selection').textContent='Selected order · '+p.key.split('/').join(' / ')+' sacks';
 el('stock').textContent='After delivery: '+p.stock.map((v,i)=>v+' kg '+names[i].toLowerCase()).join(', ')+'. Shelf space free: '+(90-sum(p.stock))+' kg.';
 el('scenarios').innerHTML=scenario('Typical week',typical,p.stock)+scenario('High-demand week',weeks[5],p.stock);
 el('weeks').innerHTML=weeks.map((w,i)=>'<tr>'+cells([i+1,...w,sum(p.outcomes[i].short),sum(p.outcomes[i].left)])+'</tr>').join('');
}
picker.onchange=()=>selectPlan(picker.value);
el('compare').onclick=e=>{if(e.target.dataset.key)selectPlan(e.target.dataset.key)};
selectPlan(ranked[0].key);
</script></body></html>
EOF
