/bin/zsh -lc "node <<'JS'
const fs=require('fs'),vm=require('vm'),assert=require('assert/strict');
const html=fs.readFileSync('index.html','utf8');
const nodes=new Map();
const ctx={document:{getElementById(id){if("'!nodes.has(id))nodes.set(id,{options:[],add(o){this.options.push(o)}});return nodes.get(id)}},Option:class{constructor(text,value){Object.assign(this,{text,value})}}};
vm.createContext(ctx);
vm.runInContext(html.match(/<script>(['"\\s\\S]*?)<\\/script>/)[1],ctx);
const picker=nodes.get('orders');
assert.equal(picker.options.length,147);assert.equal(picker.value,'2/2/3');
assert.match(nodes.get('scenarios').innerHTML,/<td>Total<\\/td><td>72<\\/td><td>0<\\/td><td>12<\\/td>/);
assert.match(nodes.get('scenarios').innerHTML,/<td>Total<\\/td><td>83<\\/td><td>2<\\/td><td>3<\\/td>/);
for(const opt of picker.options){picker.value=opt.value;picker.onchange();assert.ok(nodes.get('stock').textContent.match(/free: \\d+ kg/));assert.equal(nodes.get('weeks').innerHTML.split('<tr>').length-1,6)}
nodes.get('compare').onclick({target:{dataset:{key:'2/2/2'}}});assert.equal(picker.value,'2/2/2');
console.log('Verified 147 selections, six weekly outcomes each, recommendation, scenario totals and comparison control.');
JS"
